        }

        private TaskEvent parseTaskEvent(String line) {
            String[] parts = line.split(",");
            if (parts.length < 6) return null;

            try {
                long timestamp = Long.parseLong(parts[0]);
                // parts[1] is empty (task name)
                long jobId = Long.parseLong(parts[2]);
                long attemptId = parts[3].isEmpty() ? 0 : Long.parseLong(parts[3]);
                long taskId = parts[4].isEmpty() ? 0 : Long.parseLong(parts[4]);
                int eventType = Integer.parseInt(parts[5]);
                String taskStatus = parts.length > 6 ? parts[6] : "";

                return new TaskEvent(timestamp, jobId, attemptId, taskId, eventType, taskStatus);
            } catch (Exception e) {
                return null;
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }
